async function state(value){await page.evaluate(s=>{const f=window.tradingFixture;f.state(f.store.getSnapshot().focused_panel_id,s);},value);await page.waitForTimeout(180);}
async function geometry(){const g=await panel().evaluate(e=>({viewport:innerWidth,document:document.documentElement.scrollWidth,panels:[...e.querySelectorAll('[data-workspace-section]')].map(n=>({id:n.dataset.workspaceSection,w:n.clientWidth,scroll:n.scrollWidth})),header:{w:e.querySelector('header[data-stable]').clientWidth,scroll:e.querySelector('header[data-stable]').scrollWidth}}));assert.ok(g.document<=g.viewport);assert.ok(g.header.scroll<=g.header.w+1,JSON.stringify(g));assert.ok(g.panels.every(p=>p.scroll<=p.w+1),JSON.stringify(g));return g;}
async function toolbarFits(){const result=await page.evaluate(()=>{const bar=document.querySelector('[class*="WorkspaceHost_header_"]');const controls=[...bar.querySelectorAll('button')].filter(e=>e.checkVisibility()&&!e.closest('[inert],[aria-hidden="true"]')&&(!e.closest('ul')||e.getAttribute('aria-pressed')==='true')).map(e=>({label:e.getAttribute('aria-label')??e.textContent,rect:(()=>{const r=e.getBoundingClientRect().toJSON();for(let a=e.parentElement;a;a=a.parentElement){const style=getComputedStyle(a);if(/auto|scroll|hidden|clip/.test(style.overflowX)){const b=a.getBoundingClientRect();r.left=Math.max(r.left,b.left);r.right=Math.min(r.right,b.right);}}r.x=r.left;r.width=Math.max(0,r.right-r.left);return r;})(),hit:true}));for(const c of controls){const e=[...bar.querySelectorAll('button')].find(e=>(e.getAttribute('aria-label')??e.textContent)===c.label);const r=c.rect;c.hit=r.width>=20&&e.contains(document.elementFromPoint(r.x+r.width/2,r.y+r.height/2));}const overlaps=[];for(let i=0;i<controls.length;i++)for(let j=i+1;j<controls.length;j++){const a=controls[i],b=controls[j];if(Math.min(a.rect.right,b.rect.right)-Math.max(a.rect.left,b.rect.left)>1&&Math.min(a.rect.bottom,b.rect.bottom)-Math.max(a.rect.top,b.rect.top)>1)overlaps.push([a.label,b.label]);}return{controls,overlaps};});assert.deepEqual(result.overlaps,[]);assert.ok(result.controls.every(c=>c.hit),JSON.stringify(result));(evidence.toolbars??=[]).push(result);}
async function fundingReady(){await page.waitForFunction(()=>[...document.querySelectorAll('[data-workspace-section="chart"] [data-tradingview-plot][data-ready]')].some(p=>p.querySelector('canvas')&&p.getBoundingClientRect().width>20));}
